def board(dst, rows, footer):
    size=600; header=38; canvas=Image.new('RGB',(size*len(rows[0]),(size+header)*len(rows)+68),(23,25,29))
    draw=ImageDraw.Draw(canvas); font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',19)
    for rowi,row in enumerate(rows):
        for coli,(path,label) in enumerate(row):
            im=Image.open(path).convert('RGB'); assert im.size==(800,800)
            canvas.paste(im.resize((size,size),Image.Resampling.LANCZOS),(coli*size,rowi*(size+header)+header))
            draw.text((coli*size+12,rowi*(size+header)+9),label,font=font,fill='white')
    draw.multiline_text((12,canvas.height-58),footer,font=font,fill=(235,210,155),spacing=6)
    canvas.save(dst)

